def _t(x) -> Tensor:
    return torch.as_tensor(x, dtype=DTYPE)


def _f32(x) -> Tensor:
    return torch.as_tensor(x, dtype=torch.float32)


def _plegendre_f32(lmax: int, x: Tensor) -> list[Tensor]:
    """P_0..P_lmax at `x` by plegendre.f90's upward recurrence, in `real(sgl)`.

    `plegendre` is declared `real(sgl)` and every barsierk fit sums coefficients of order 1e6
    down to a barrier of order 1 MeV, so the single-precision rounding is not noise we may
    discard -- it IS the number TALYS uses (see `barsierk`).

    TALYS: plegendre.f90:1 (plegendre)
    Test: tests/hf/test_fission_systematics.py
    """
    pl = [_f32(1.0), x]
    for i in range(2, lmax + 1):
        pl.append((x * _f32(2 * i - 1) * pl[i - 1] - _f32(i - 1) * pl[i - 2]) / _f32(i))
    return pl[: lmax + 1]


def barsierk(iz: int, ia: int, il: int) -> tuple[Tensor, Tensor, Tensor]:
    """Sierk barrier height, rotating ground-state energy and the l at which the barrier vanishes.

    Returns ``(bfis, egs, lbar0)`` in MeV (and hbar for `lbar0`). Outside Sierk's validity
    (Z < 19, Z > 111, or A outside ``1.2Z + 0.01Z^2 .. 5.8Z - 0.024Z^2``) TALYS prints a warning
    and leaves all three at zero; this port returns zeros silently, because `fissionpar` then
    falls through to the `fwidth` default and the caller sees `fbarrier = 0`.

    Every variable of barsierk.f90 is declared `real(sgl)`, and this routine is one of the few
    places where that matters: the `barcof` fit sums 49 terms of order 1e6 down to a barrier of
    order 1 MeV, so ~6 digits cancel and the float32 rounding of the partial sums is a
    0.1-0.6 MeV shift of the answer, not a rounding artefact to be improved away. Evaluating the
    same sum in float64 gives Am-307 1.482 MeV where TALYS gets 1.745. On nuclei whose barrier
    sits near the excitation energy that 0.26 MeV is a factor ~1e3 in the Hill-Wheeler
    transmission and therefore in the capture cross section that competes with fission
    (docs/results/actld5-sierk-precision.md). So the sums run in float32, in TALYS's order, and
    only the result is widened to `DTYPE`.

    TALYS: barsierk.f90:1 (barsierk)
    Test: A-fis (ungated: no reference target reaches `fismodel 3`),
          tests/hf/test_fission_systematics.py
    """
    zero = torch.zeros((), dtype=DTYPE)
    if iz < 19 or iz > 111 or (iz > 102 and il > 0):
        return zero, zero, zero
    zchar, amass, ll = float(iz), float(ia), float(il)
    amin = 1.2 * zchar + 0.01 * zchar * zchar
    amax = 5.8 * zchar - 0.024 * zchar * zchar
    if amass < amin or amass > amax:
        return zero, zero, zero
    a, z, l = _f32(amass / 400.0), _f32(zchar / 100.0), _f32(ll / 100.0)
    pz = _plegendre_f32(6, z)
    pa = _plegendre_f32(6, a)
    # barcof(jloop, iloop) with jloop the Z index and iloop the A index (barsierk.f90:88)
    bfis = _f32(0.0)
    for i in range(7):  # iloop, the A index, is the outer loop
        for j in range(7):
            bfis = bfis + _f32(BARCOF[j][i]) * pz[j] * pa[i]
    if il < 1:
        return bfis.to(DTYPE), zero, zero

    amin2 = 1.4 * zchar + 0.009 * zchar * zchar
    amax2 = 20.0 + 3.0 * zchar
    if amass < amin2 - 5.0 or amass > amax2 + 10.0:
        return bfis.to(DTYPE), zero, zero

    def _fit(cof, nj: int, ni: int) -> Tensor:
        acc = _f32(0.0)
        for i in range(ni):
            for j in range(nj):
                acc = acc + _f32(cof[j][i]) * pz[j] * pa[i]
        return acc

    l80 = _fit(L80COF, 5, 4)
    l20 = _fit(L20COF, 5, 4)
    lbar0 = _fit(LMXCOF, 6, 4)

    x, y = l20 / lbar0, l80 / lbar0
    if ll > float(l20):
        p1 = (-(20.0 * x**5) + 25.0 * x**4 - 4.0) * (y - 1.0) ** 2 * y * y
        p2 = (-(20.0 * y**5) + 25.0 * y**4 - 1.0) * (x - 1.0) ** 2 * x * x
        q1 = 0.2 / ((y - x) * ((1.0 - x) * (1.0 - y) * x * y) ** 2)
        q2 = q1 * (p1 * y - p2 * x)
        q3 = -(q1 * (p1 * (2.0 * y + 1.0) - p2 * (2.0 * x + 1.0)))
        r = ll / lbar0
        a1 = 4.0 * r**5 - 5.0 * r**4 + 1.0
        a2 = q2 * (2.0 * r + 1.0)
        bfis = bfis * (a1 + (r - 1.0) * (a2 + q3 * r) * r * r * (r - 1.0))
    else:
        q1 = 0.2 / (l20**2 * l80**2 * (l20 - l80))
        q2 = q1 * (4.0 * l80**3 - l20**3)
        q3 = -(q1 * (4.0 * l80**2 - l20**2))
        bfis = bfis * (1.0 + q2 * ll**2 + q3 * ll**3)
    if float(bfis) <= 0.0 or ll > float(lbar0):
        bfis = _f32(0.0)
    if ll > float(lbar0):
        return bfis.to(DTYPE), zero, lbar0.to(DTYPE)
    pl = _plegendre_f32(8, l)
    egs = _f32(0.0)
    for i in range(4):
        for j in range(6):
            for k in range(5):
                egs = egs + _f32(EGSCOF[k][j][i]) * pz[j] * pa[i] * pl[2 * k]
    egs = torch.clamp(egs, min=0.0)
    return bfis.to(DTYPE), egs.to(DTYPE), lbar0.to(DTYPE)


def rldm(iz: int, ia: int, il: int) -> tuple[Tensor, Tensor]:
    """Rotating-liquid-drop ground-state and saddle-point energies `(egs, esp)` [MeV].

    Bilinear interpolation of Cohen-Plasil-Swiatecki's tabulated ``Bf/Es`` and ``Er/Es`` on one
    of three (x, y) grids chosen by the fissility ``x``, exactly as the arithmetic-IF cascade
    of rldm.f90:65-94.

    TALYS: rldm.f90:1 (rldm)
    Test: A-fis (ungated: no reference target reaches `fismodel 4`)
    """
    zchar, amass, ll = float(iz), float(ia), float(il)
    neut = amass - zchar
    paren = 1.0 - 1.7826 * ((neut - zchar) / amass) ** 2
    eso = 17.9439 * paren * amass**0.666666
    x = 0.019655 * zchar * (zchar / amass) / paren
    ero = 34.548 * ll * ll / amass**1.666666
    y = 1.9254 * ll * ll / (paren * amass**2.3333333)
    ix = int(20.0 * x + 1.0)
    # rldm.f90:68-71 stores int(20x+1) into a real and subtracts real(ix) from it, so the
    # interpolation fraction in x is identically zero. Reproduced as written.
    dx = 0.0
    if x <= 0.25:
        by = min(max(10.0 * y + 1.0, 1.0), 9.0)
        tabh, tabb = X1H, X1B
    elif x <= 0.5:
        by = min(max(20.0 * y + 1.0, 1.0), 10.0)
        ix -= 5
        tabh, tabb = X2H, X2B
    else:
        x = min(x, 0.95)
        ix = int(20.0 * x + 1.0) - 10
        by = min(max(100.0 * y + 1.0, 1.0), 19.0)
        tabh, tabb = X3H, X3B
    iy = int(by)
    dy = by - float(iy)
    nrow, ncol = len(tabh), len(tabh[0])
    ix = max(1, min(ix, nrow - 1))
    iy = max(1, min(iy, ncol - 1))

    def interp(tab) -> float:
        v1 = (tab[ix][iy - 1] - tab[ix - 1][iy - 1]) * dx + tab[ix - 1][iy - 1]
        v2 = (tab[ix][iy] - tab[ix - 1][iy]) * dx + tab[ix - 1][iy]
        return (v2 - v1) * dy + v1

    hf = interp(tabh)
    bfrldm = interp(tabb)
    egs = _t(ero + hf * eso)
    return egs, _t(float(egs) + bfrldm * eso)


__all__ = ["barsierk", "rldm"]
